// Generate a random regex pattern string (1..4096 bytes guaranteed by runtime)
std::string pattern = FUZZ_PARAM_STR();
// Call the target function
cregex_node_t *root = cregex_parse(pattern.c_str());
// Require successful parse to hand a valid object to the pool
if (!root) { FUZZ_BAIL(); }
// Track provenance and basic lifetime state
FUZZ_SET_ATTR_INT(root, "parsed", 1);
FUZZ_SET_ATTR_INT(root, "freed", 0);
FUZZ_SET_ATTR_STR(root, "pattern", pattern.c_str());
// root is returned to the pool as an output object

// Enforce that root came from cregex_parse and hasn't been freed
if (FUZZ_GET_ATTR_INT(root, "parsed") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(root, "freed") != 0) { FUZZ_BAIL(); }
// Compile the AST into a program
cregex_program_t *program = cregex_compile_node(root);
if (!program) { FUZZ_BAIL(); }
// Track provenance and lifetime for the compiled program
FUZZ_SET_ATTR_INT(program, "compiled", 1);
FUZZ_SET_ATTR_INT(program, "freed", 0);
// Return both root (still owned by caller) and the new program to the pool

// Validate input program was produced by cregex_compile_node and not freed
if (FUZZ_GET_ATTR_INT(program, "compiled") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(program, "freed") != 0) { FUZZ_BAIL(); }
// Generate an input string; keep the std::string alive across the call
std::string input = FUZZ_PARAM_STR();
// Choose a small nmatches >= 0
unsigned int r = *FUZZ_PARAM(unsigned int);
int nmatches = (int)(r % 9); // 0..8 to keep storage modest
// Prepare matches storage per contract: if nmatches > 0, provide writable array; otherwise pass NULL with nmatches == 0
const char **matches_ptr = nullptr;
std::vector<const char *> matches_vec;
if (nmatches > 0) {
    matches_vec.assign((size_t)nmatches, nullptr);
    matches_ptr = matches_vec.data();
} else {
    nmatches = 0;
    matches_ptr = nullptr;
}
// Execute the program. We do not assert return semantics as they are undocumented.
( void )cregex_program_run(program, input.c_str(), matches_ptr, nmatches);
// Return program to the pool unchanged

// Enforce single free and correct provenance
if (FUZZ_GET_ATTR_INT(program, "compiled") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(program, "freed") != 0) { FUZZ_BAIL(); }
// Free the program and mark as freed
cregex_compile_free(program);
FUZZ_SET_ATTR_INT(program, "freed", 1);
// Do not return program to the pool to avoid use-after-free

// Enforce single free and correct provenance
if (FUZZ_GET_ATTR_INT(root, "parsed") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(root, "freed") != 0) { FUZZ_BAIL(); }
// Free the parse tree and mark as freed
cregex_parse_free(root);
FUZZ_SET_ATTR_INT(root, "freed", 1);
// Do not return root to the pool to avoid use-after-free

// Prepare a valid, initialized character-class bitset buffer
cregex_char_class klass;
std::memset(klass, 0, sizeof(klass));
// Add a few in-range characters to the class to ensure meaningful contains checks
unsigned int a = *FUZZ_PARAM(unsigned int) % 256u;
unsigned int b = *FUZZ_PARAM(unsigned int) % 256u;
unsigned int c = *FUZZ_PARAM(unsigned int) % 256u;
( void )cregex_char_class_add(klass, (int)a);
( void )cregex_char_class_add(klass, (int)b);
( void )cregex_char_class_add(klass, (int)c);
// Query membership for a random in-range character
unsigned int q = *FUZZ_PARAM(unsigned int) % 256u;
( void )cregex_char_class_contains(klass, (int)q);
// Property: characters explicitly added must be detected as present
FUZZ_ASSERT(cregex_char_class_contains(klass, (int)a) != 0, "added char a must be contained");

// Prepare a valid, writable, zero-initialized bitset buffer
cregex_char_class klass;
std::memset(klass, 0, sizeof(klass));
// Choose an in-range character and add it
unsigned int ch = *FUZZ_PARAM(unsigned int) % 256u;
int ret = cregex_char_class_add(klass, (int)ch);
// Ensure API returned the added character and membership now holds
FUZZ_ASSERT(ret == (int)ch, "cregex_char_class_add should return the added character code");
FUZZ_ASSERT(cregex_char_class_contains(klass, (int)ch) != 0, "added character must be contained in class");

