import random
import string

# Regex pattern generator for cregex_parse
# Goal: produce varied but valid patterns featuring literals, classes, quantifiers,
# groups, alternations, anchors, and escapes while keeping within 4096 bytes.

LITERALS = [
    "a", "b", "c", "x", "y", "z",
    "A", "B", "C", "X", "Y", "Z",
    "0", "1", "2", "7", "8", "9",
]

ESCAPES_SIMPLE = ["\\d", "\\D", "\\w", "\\W", "\\s", "\\S", "\\t", "\\n", "\\r", "\\f", "."]

# Common character class ranges and atoms
CLASS_RANGES = [
    ("a", "z"), ("A", "Z"), ("0", "9"),
]
CLASS_ATOMS = list("._-:@ ") + list("aeiouAEIOU13579")

QUANT_SIMPLE = ["*", "+", "?", "*?", "+?", "??"]

# Some bounded quantifiers; we will also synthesize random {m,n}
BOUNDED_PRESETS = ["{0}", "{1}", "{2}", "{3}", "{4}", "{5}", "{1,2}", "{2,3}", "{0,3}", "{3,}"]

ANCHORS = ["^", "$"]

MAX_LEN = 4096


def rand_choice(rng, seq):
    return seq[rng.randrange(len(seq))]


def rand_literal(rng):
    # Either a simple literal or an escaped special
    choice = rng.random()
    if choice < 0.6:
        return rand_choice(rng, LITERALS)
    elif choice < 0.85:
        # Escape a metachar to force literal
        return "\\" + rand_choice(rng, [".", "*", "+", "?", "(", ")", "[", "]", "{", "}", "|", "^", "$", "\\"])
    else:
        return rand_choice(rng, ESCAPES_SIMPLE)


def rand_class(rng):
    # Build a character class like [a-zA-Z0-9_], with optional negation
    parts = []
    # Randomly decide negation
    neg = rng.random() < 0.2
    # Add some ranges
    for _ in range(rng.randint(0, 3)):
        a, b = rand_choice(rng, CLASS_RANGES)
        parts.append(f"{a}-{b}")
    # Add some single atoms
    for _ in range(rng.randint(1, 5)):
        ch = rand_choice(rng, CLASS_ATOMS)
        # Escape class special chars
        if ch in "^-[]\\":
            ch = "\\" + ch
        parts.append(ch)
    inner = "".join(parts) if parts else "a"
    return ("[^" if neg else "[") + inner + "]"


def rand_quantifier(rng):
    if rng.random() < 0.6:
        return rand_choice(rng, QUANT_SIMPLE)
    if rng.random() < 0.5:
        return rand_choice(rng, BOUNDED_PRESETS)
    # Generate {m,n} where 0 <= m <= n <= 10 or {m,}
    m = rng.randint(0, 5)
    if rng.random() < 0.7:
        n = rng.randint(m, m + 10)
        return f"{{{m},{n}}}"
    else:
        return f"{{{m},}}"


def rand_atom(rng, depth):
    # Base element that can be quantified
    r = rng.random()
    if depth < 2 and r < 0.25:
        return rand_group(rng, depth + 1)
    elif r < 0.5:
        return rand_literal(rng)
    elif r < 0.75:
        return rand_class(rng)
    else:
        return "."


def maybe_quantify(rng, atom):
    if rng.random() < 0.6:
        return atom + rand_quantifier(rng)
    return atom


def rand_concat(rng, depth):
    # Concatenate 1..N quantified atoms
    n = 1 + int(rng.random() ** 0.6 * 6)  # bias to smaller counts
    parts = []
    for _ in range(n):
        atom = rand_atom(rng, depth)
        parts.append(maybe_quantify(rng, atom))
    return "".join(parts)


def rand_alternation(rng, depth):
    # Build A|B|C with 2..k branches
    k = 2 + int(rng.random() ** 0.5 * 3)  # 2..4 branches
    branches = []
    for _ in range(k):
        branches.append(rand_concat(rng, depth))
    return "|".join(branches)


def rand_group(rng, depth):
    # Capturing or non-capturing group; include anchors optionally inside/outside
    kind = rng.random()
    if kind < 0.75:
        inner = rand_branching(rng, depth)
        return "(" + inner + ")"
    else:
        inner = rand_branching(rng, depth)
        return "(?:" + inner + ")"


def rand_branching(rng, depth):
    if rng.random() < 0.4:
        return rand_alternation(rng, depth)
    else:
        return rand_concat(rng, depth)


def with_anchors(rng, pattern):
    # Optionally add ^ and/or $ ensuring they appear at ends
    if rng.random() < 0.5:
        pattern = "^" + pattern
    if rng.random() < 0.5:
        pattern = pattern + "$"
    return pattern


def sprinkle_saves_like_groups(rng, pattern):
    # Encourage more groups and nested structures by occasionally wrapping segments
    # without exceeding size budget.
    if len(pattern) > MAX_LEN // 2:
        return pattern
    pieces = []
    i = 0
    while i < len(pattern):
        j = min(len(pattern), i + rng.randint(3, 12))
        segment = pattern[i:j]
        if rng.random() < 0.25:
            segment = "(" + segment + ")"  # capturing wrapper
            if rng.random() < 0.3:
                segment += rand_quantifier(rng)
        pieces.append(segment)
        i = j
    out = "".join(pieces)
    return out if len(out) <= MAX_LEN else pattern


def make_pattern(rng):
    # Choose a generation strategy
    strategies = []
    # 1) Simple literal string
    def strat_literal():
        n = rng.randint(1, 20)
        return "".join(rand_literal(rng) for _ in range(n))

    # 2) A single complex alternation
    def strat_alt():
        return with_anchors(rng, rand_alternation(rng, 0))

    # 3) Concatenation with classes and quantifiers
    def strat_concat():
        p = rand_concat(rng, 0)
        return with_anchors(rng, p)

    # 4) Nested groups with alternations
    def strat_nested():
        p = rand_group(rng, 0)
        if rng.random() < 0.6:
            p = maybe_quantify(rng, p)
        return with_anchors(rng, p)

    # 5) Predefined interesting patterns
    def strat_presets():
        presets = [
            "^$",
            "^.*$",
            "(a|b|c)+",
            "(\d{1,3}\.){3}\d{1,3}",
            "(foo|bar)?baz",
            "[A-Za-z_][A-Za-z0-9_]*",
            "(ab)*?c",
            "^(.+)$",
            "(a(?:b|c){0,3}d)+",
            "[^\n]*\n",
        ]
        return rand_choice(rng, presets)

    strategies = [strat_literal, strat_alt, strat_concat, strat_nested, strat_presets]
    p = rand_choice(rng, strategies)()

    # Optional post-processing to increase structural variety
    if rng.random() < 0.4:
        p = sprinkle_saves_like_groups(rng, p)

    # Ensure not empty and within size
    if not p:
        p = "a"
    return p[:MAX_LEN]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Randomly generate 1..N concatenated subpatterns with outer grouping or alternation
    parts = []
    num = 1 + int(rng.random() ** 0.5 * 4)  # 1..3, bias toward 1-2
    for _ in range(num):
        parts.append(make_pattern(rng))
    pattern = parts[0] if len(parts) == 1 else "(" + ")|(".join(parts) + ")"

    # Trim if necessary
    if len(pattern) > MAX_LEN:
        pattern = pattern[:MAX_LEN]

    # Return as bytes (null-terminated not required here; harness treats string data)
    return pattern.encode("utf-8", errors="ignore")
